import json,sys
t=json.load(open('/work/trace.json'))['rows']
def run(step, verbose=False):
    R=[None]*4; ok=bad=0
    for k in range(len(t)-1):
        r=t[k]; n=t[k+1]
        if r[0]: R=[0]*4; continue
        if not r[2]: continue
        i=r[1]
        if i>>2==0x1c:
            v=R[i&3]
            if v is not None:
                if v==n[3]: ok+=1
                else:
                    bad+=1
                    if verbose: print('mismatch row',k,'r%d'%(i&3),'pred',v,'act',n[3])
            R[i&3]=n[3]
            continue
        step(R,i)
    return ok,bad
def step(R,i):
    if i>>6==2:
        d=(i>>4)&3; R[d]=None if R[d] is None else ((R[d]<<4)|(i&15))&255
    else:
        R[(i>>2)&3]=None
print(run(step,True))
