import json,sys
t=json.load(open('/work/trace.json'))['rows']
def make(op0, zops, sh='imm'):
  def alu(op,a,b,rs,Z):
    if op==0: return op0(a,b,Z)
    if op==1: return b
    if op==2: return a+b
    if op==3: return a-b
    if op==4: return a&b
    if op==5: return a^b
    if op==6: return a<<(rs+1) if sh=='imm' else a<<(b&7)
    if op==0xc: return a+1
    if op==0xd: return a-1
    if op==0xe: return a-b
    if op==0xf: return ~a
  return alu
def run(alu,ZOPS,verbose=False):
  R=[None]*4; Z=None; bad=0; chk=0
  for k in range(len(t)-1):
    r=t[k]; n=t[k+1]
    if r[0]: R=[0]*4; Z=0
    elif r[2]:
        i=r[1]
        if i>>2==0x1c:
            s=i&3
            if R[s] is not None:
                chk+=1
                if R[s]!=n[3]:
                    bad+=1
                    if verbose: print('OUTMIS row',k,'%02x'%i,'pred',R[s],'act',n[3])
            R[s]=n[3]
        elif i>>6==2:
            d=(i>>4)&3; R[d]=None if R[d] is None else ((R[d]<<4)|(i&15))&255
        else:
            op=i>>4; rd=(i>>2)&3; rs=i&3; a,b=R[rd],R[rs]
            res=None
            if a is not None and b is not None and Z is not None: res=alu(op,a,b,rs,Z)
            if res is not None: res&=255
            if op in ZOPS: Z=None if res is None else int(res==0)
            if op not in (0xe,0x7): R[rd]=res
    if Z is not None:
        chk+=1
        if Z!=n[5]:
            if verbose: print('ZMIS row',k,'%02x'%r[1],'pred',Z,'act',n[5])
            bad+=1; Z=n[5]
    if Z is None: Z=n[5]
  return bad,chk
Z0={2,3,4,5,6,0xc,0xd,0xe,0xf}
for name,f in [('unk',lambda a,b,Z:None),('nop',lambda a,b,Z:a),('cmovz',lambda a,b,Z:b if Z else a),('cmovnz',lambda a,b,Z:a if Z else b),('or',lambda a,b,Z:a|b)]:
  for zo in [Z0, Z0|{0}]:
    print(name, 0 in zo, run(make(f,zo),zo))
print('shift by b', run(make(lambda a,b,Z:None,Z0,'b'),Z0))
